from pathlib import Path
import hashlib, json, os, sys

ROOT = Path.cwd().resolve()
LEDGER = ROOT / "knowledge/failure_class_ledger.json"
BACKUP = ROOT / "state/governance/backups/gov1_cycle_a_ledger_before.json"
TEMP = ROOT / "knowledge/.failure_class_ledger.gov1_cycle_a.tmp"
ROLLBACK = ROOT / "knowledge/.failure_class_ledger.gov1_cycle_a.rollback.tmp"
EXPECTED = "12a0c025fdb69fdb321e0574c48d1ac0fe5407364bc769207987c8326361a954"
WANTED = {"G-001", "G-002", "G-003", "G-004", "G-005", "G-006"}

def sha(path):
    return hashlib.sha256(path.read_bytes()).hexdigest()

def write_xb(path, data):
    path.parent.mkdir(parents=True, exist_ok=True)
    with path.open("xb") as f:
        f.write(data)
        f.flush()
        os.fsync(f.fileno())

changed = False
try:
    if sha(LEDGER) != EXPECTED:
        raise RuntimeError("LEDGER_SHA_MISMATCH")
    raw = LEDGER.read_bytes()
    text = raw.decode("utf-8")
    payload = json.loads(text)
    if payload.get("version") != 1:
        raise RuntimeError("LEDGER_VERSION_MISMATCH")
    if not isinstance(payload.get("classes"), list) or len(payload["classes"]) != 6:
        raise RuntimeError("LEDGER_CLASS_SET_MISMATCH")
    found = {}
    for item in payload["classes"]:
        hits = WANTED & set(item.get("aliases", []))
        if len(hits) != 1:
            raise RuntimeError("LEDGER_ALIAS_SET_MISMATCH")
        gid = next(iter(hits))
        if gid in found:
            raise RuntimeError("LEDGER_DUPLICATE_CLASS")
        ev = item.get("closure_evidence", {})
        if item.get("status") != "CLOSED":
            raise RuntimeError(f"{gid}_STATUS_MISMATCH")
        if ev.get("validator_version") != "1.0.0":
            raise RuntimeError(f"{gid}_VALIDATOR_MISMATCH")
        if "ledger_version" in ev:
            raise RuntimeError(f"{gid}_LEDGER_BIND_UNEXPECTED")
        found[gid] = item
    if set(found) != WANTED:
        raise RuntimeError("LEDGER_WANTED_SET_MISMATCH")
    if BACKUP.exists() or TEMP.exists() or ROLLBACK.exists():
        raise RuntimeError("FRESH_PATH_REQUIRED")
    write_xb(BACKUP, raw)
    if sha(BACKUP) != EXPECTED:
        raise RuntimeError("BACKUP_SHA_MISMATCH")
    if text.count('"status": "CLOSED"') != 6:
        raise RuntimeError("STATUS_TEXT_SHAPE_MISMATCH")
    version_marker = '\n  "version": 1\n}\n'
    if text.count(version_marker) != 1:
        raise RuntimeError("VERSION_TEXT_SHAPE_MISMATCH")
    updated = text.replace('"status": "CLOSED"', '"status": "REOPENED"')
    updated = updated.replace(version_marker, '\n  "version": 2\n}\n')
    write_xb(TEMP, updated.encode("utf-8"))
    os.replace(TEMP, LEDGER)
    changed = True
    check = json.loads(LEDGER.read_text(encoding="utf-8"))
    if check.get("version") != 2:
        raise RuntimeError("POST_VERSION_MISMATCH")
    statuses = {}
    for item in check.get("classes", []):
        hits = WANTED & set(item.get("aliases", []))
        if len(hits) == 1:
            statuses[next(iter(hits))] = item.get("status")
    if statuses != {gid: "REOPENED" for gid in WANTED}:
        raise RuntimeError("POST_STATUS_MISMATCH")
    print("CYCLE_A_MUTATION:PASS")
    print("LEDGER_VERSION=2")
    print("G001_G006_STATUS=REOPENED")
except Exception as error:
    if changed:
        try:
            write_xb(ROLLBACK, BACKUP.read_bytes())
            os.replace(ROLLBACK, LEDGER)
            if sha(LEDGER) != EXPECTED:
                raise RuntimeError("ROLLBACK_SHA_MISMATCH")
            print("ROLLBACK:PASS", file=sys.stderr)
        except Exception as rollback_error:
            print(f"ROLLBACK:FAIL:{type(rollback_error).__name__}", file=sys.stderr)
    print(f"CYCLE_A_MUTATION:FAIL:{type(error).__name__}:{error}", file=sys.stderr)
    sys.exit(1)
